"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["34455"],{2835(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.idade_maxima_emissao.fase_extremo_ausente","status":422,"titulo":"A fase que inicia a contagem da idade m\xe1xima de emiss\xe3o n\xe3o tem definida a data de in\xedcio ou de t\xe9rmino usada na contagem; defina essa data na fase"},"descricao":{"codigo":"uniplus.selecao.idade_maxima_emissao.fase_extremo_ausente","requisitos":["UNI-REQ-0066"],"oQueAconteceu":["A idade m\xe1xima de emiss\xe3o de um documento exigido usa como refer\xeancia o in\xedcio ou o fim de uma fase do\\ncronograma, e essa data n\xe3o est\xe1 definida. O sistema n\xe3o escolhe outra data no lugar (a mensagem\\ndiz que n\xe3o h\xe1 alternativa silenciosa), porque uma refer\xeancia sem data definida deixaria o limite de idade\\nsem refer\xeancia. Os casos s\xe3o estes:","- na defini\xe7\xe3o dos documentos exigidos, a fase de refer\xeancia de `INICIO_FASE` n\xe3o tem in\xedcio, ou a de\\n  `FIM_FASE` n\xe3o tem fim;\\n- na defini\xe7\xe3o dos documentos exigidos, o tipo \xe9 `FIM_INSCRICAO` e nenhuma fase que coleta\\n  inscri\xe7\xe3o tem fim definido;\\n- na defini\xe7\xe3o do cronograma de fases, uma fase que continua no cronograma perde o in\xedcio ou o fim\\n  que um documento exigido usa como refer\xeancia;\\n- na defini\xe7\xe3o do cronograma de fases, a redefini\xe7\xe3o deixa de ter uma fase que coleta inscri\xe7\xe3o com\\n  fim definido, e h\xe1 documento com idade m\xe1xima contada a partir de `FIM_INSCRICAO`.","A idade m\xe1xima de emiss\xe3o \xe9 uma regra opcional de cada documento exigido: limita h\xe1 quanto tempo o\\ncomprovante enviado pode ter sido emitido (por exemplo, no m\xe1ximo 90 dias), contado a partir de um\\nmarco de refer\xeancia. Ela \xe9 dada por um valor, uma unidade (`DIAS`, `MESES` ou `ANOS`) e o tipo de\\nrefer\xeancia: `FIM_INSCRICAO`, `INICIO_FASE`, `FIM_FASE`, `DATA_ESPECIFICA` ou `DATA_SUBMISSAO`. Ela funciona como\\naviso e n\xe3o bloqueia a presen\xe7a do documento. A regra \xe9 tudo ou nada: ou os tr\xeas campos est\xe3o\\nausentes (sem regra), ou os tr\xeas est\xe3o presentes, com a data quando o tipo \xe9 `DATA_ESPECIFICA` e a fase\\nquando \xe9 `INICIO_FASE` ou `FIM_FASE`.","Na defini\xe7\xe3o dos documentos exigidos, esta confer\xeancia vem depois da de a fase existir no\\ncronograma ([`fase_nao_pertence_ao_processo`](/erros/uniplus.selecao.idade_maxima_emissao.fase_nao_pertence_ao_processo)). Na defini\xe7\xe3o do cronograma, a confer\xeancia\\nda fase que continua vem depois da da consequ\xeancia de reenvio da mesma fase, e a de\\n`FIM_INSCRICAO` vem depois das confer\xeancias de todas as fases. Nada \xe9 gravado."],"comoResolver":["Na defini\xe7\xe3o dos documentos exigidos, defina no cronograma o in\xedcio ou o fim da fase de refer\xeancia, ou\\nescolha outra refer\xeancia, e envie a defini\xe7\xe3o de novo.","Na defini\xe7\xe3o do cronograma, mantenha o in\xedcio ou o fim que o documento usa como refer\xeancia, ou ajuste\\nantes a exig\xeancia nomeada na defini\xe7\xe3o de documentos exigidos, apontando a refer\xeancia para outra fase ou\\nretirando o limite, e repita a defini\xe7\xe3o do cronograma."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Idade maxima emissao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);